selector_to_html = {"a[href=\"../glossary.html#term-gosodiad-neilltuad\"]": "<dt id=\"term-gosodiad-neilltuad\">gosodiad neilltuad</dt><dd><p>assignment statement</p></dd>", "a[href=\"../glossary.html#term-sylwad\"]": "<dt id=\"term-sylwad\">sylwad</dt><dd><p>comment (in code)</p></dd>", "a[href=\"../glossary.html#term-gweithredydd-dot\"]": "<dt id=\"term-gweithredydd-dot\">gweithredydd dot</dt><dd><p>dot operator</p></dd>", "a[href=\"../glossary.html#term-gosodiad\"]": "<dt id=\"term-gosodiad\">gosodiad</dt><dd><p>statement</p></dd>", "a[href=\"#diagramau-cyflwr\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2.2. </span>Diagramau Cyflwr<a class=\"headerlink\" href=\"#diagramau-cyflwr\" title=\"Link to this heading\">#</a></h2><p>Ffordd gyffredin o gynrychioli newidynnau ar bapur yw ysgrifennu\u2019r enw gyda saeth\nyn pwyntio at ei werth.</p>", "a[href=\"#y-gosodiad-import\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2.4. </span>Y Gosodiad Import<a class=\"headerlink\" href=\"#y-gosodiad-import\" title=\"Link to this heading\">#</a></h2><p>Er mwyn defnyddio rhai nodweddion Python, mae\u2019n rhaid i chi eu <strong>mewnforio</strong>. Er\nenghraifft, mae\u2019r gosodiad canlynol yn mewnforio\u2019r modiwl <code class=\"docutils literal notranslate\"><span class=\"pre\">math</span></code>.</p>", "a[href=\"#ymarferion\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2.11. </span>Ymarferion<a class=\"headerlink\" href=\"#ymarferion\" title=\"Link to this heading\">#</a></h2><h3><span class=\"section-number\">2.11.1. </span>Gofyn i gynorthwyydd rhithwir<a class=\"headerlink\" href=\"#gofyn-i-gynorthwyydd-rhithwir\" title=\"Link to this heading\">#</a></h3><p>Unwaith eto, rwy\u2019n eich annog i ddefnyddio cynorthwyydd rhithwir i ddysgu mwy am\nunrhyw un o bynciau\u2019r bennod hon.</p><p>Os ydych yn chwilfrydig am unrhyw un o\u2019r allweddeiriau a restrais, gallech ofyn\n\u201cPam mae class yn allweddair?\u201d neu \u201cPam na all enwau newidynnau fod yn\nallweddeiriau?\u201d</p>", "a[href=\"#newidynnau\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2.1. </span>Newidynnau<a class=\"headerlink\" href=\"#newidynnau\" title=\"Link to this heading\">#</a></h2><p>Mae <strong><a class=\"reference internal\" href=\"../glossary.html#term-newidyn\"><span class=\"xref std std-term\">newidyn</span></a></strong> yn enw sy\u2019n cyfeirio at werth. I greu newidyn, gallwn\nysgrifennu <strong><a class=\"reference internal\" href=\"../glossary.html#term-gosodiad-neilltuad\"><span class=\"xref std std-term\">gosodiad neilltuad</span></a></strong> fel hyn.</p>", "a[href=\"../glossary.html#term-allweddair\"]": "<dt id=\"term-allweddair\">allweddair</dt><dd><p>keyword</p></dd>", "a[href=\"../glossary.html#term-eithriad\"]": "<dt id=\"term-eithriad\">eithriad</dt><dd><p>exception</p></dd>", "a[href=\"../glossary.html#term-gwerthuso\"]": "<dt id=\"term-gwerthuso\">gwerthuso</dt><dd><p>evaluate / evaluation</p></dd>", "a[href=\"../glossary.html#term-cyflawniad\"]": "<dt id=\"term-cyflawniad\">cyflawniad</dt><dd><p>execution</p></dd>", "a[href=\"#newidynnau-a-gosodiadau\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2. </span>Newidynnau a Gosodiadau<a class=\"headerlink\" href=\"#newidynnau-a-gosodiadau\" title=\"Link to this heading\">#</a></h1><p>Yn y bennod flaenorol, defnyddiom weithredyddion i ysgrifennu mynegiadau sy\u2019n\nperfformio cyfrifiannau rhifyddol.</p><p>Yn y bennod hon, byddwch yn dysgu am newidynnau a gosodiadau, y gosodiad <code class=\"docutils literal notranslate\"><span class=\"pre\">import</span></code>,\na\u2019r swyddogaeth <code class=\"docutils literal notranslate\"><span class=\"pre\">print</span></code>. A byddaf yn cyflwyno rhagor o\u2019r eirfa a ddefnyddiwn i siarad\nam raglenni, gan gynnwys \u201cdadl\u201d a \u201cmodiwl\u201d.</p>", "a[href=\"../glossary.html#term-diagram-cyflwr\"]": "<dt id=\"term-diagram-cyflwr\">diagram cyflwr</dt><dd><p>state diagram</p></dd>", "a[href=\"#dadnamu\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2.9. </span>Dadnamu<a class=\"headerlink\" href=\"#dadnamu\" title=\"Link to this heading\">#</a></h2><p>Gall tri math o wallau ddigwydd mewn rhaglen: gwallau cystrawen, gwallau rhedeg, a\ngwallau semantig. Mae\u2019n ddefnyddiol gwahaniaethu rhyngddynt er mwyn eu holrhain yn\ngyflymach.</p>", "a[href=\"../glossary.html#term-gwall-semantig\"]": "<dt id=\"term-gwall-semantig\">gwall semantig</dt><dd><p>semantic error</p></dd>", "a[href=\"#dadleuon\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2.7. </span>Dadleuon<a class=\"headerlink\" href=\"#dadleuon\" title=\"Link to this heading\">#</a></h2><p>Pan fyddwch yn galw swyddogaeth, gelwir y mynegiad mewn cromfachau yn\n<strong><a class=\"reference internal\" href=\"../glossary.html#term-dadl\"><span class=\"xref std std-term\">dadl</span></a></strong>. Fel arfer byddwn yn esbonio pam, ond yn yr achos hwn nid oes gan\nystyr technegol y term bron ddim i\u2019w wneud ag ystyr cyffredin y gair, felly ni wnaf\nhyd yn oed geisio.</p><p>Mae rhai o\u2019r swyddogaethau rydym wedi\u2019u gweld hyd yn hyn yn cymryd dim ond un ddadl,\nfel <code class=\"docutils literal notranslate\"><span class=\"pre\">int</span></code>.</p>", "a[href=\"../glossary.html#term-newidyn\"]": "<dt id=\"term-newidyn\">newidyn</dt><dd><p>variable</p></dd>", "a[href=\"../glossary.html#term-modiwl\"]": "<dt id=\"term-modiwl\">modiwl</dt><dd><p>module</p></dd>", "a[href=\"#y-swyddogaeth-print\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2.6. </span>Y Swyddogaeth print<a class=\"headerlink\" href=\"#y-swyddogaeth-print\" title=\"Link to this heading\">#</a></h2><p>Pan fyddwch yn gwerthuso mynegiad, dangosir y canlyniad.</p>", "a[href=\"#mynegiadau-a-gosodiadau\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2.5. </span>Mynegiadau a Gosodiadau<a class=\"headerlink\" href=\"#mynegiadau-a-gosodiadau\" title=\"Link to this heading\">#</a></h2><p>Hyd yn hyn, rydym wedi gweld rhai mathau o fynegiadau. Gall mynegiad fod yn werth\nsengl, fel cyfanrif, rhif pwynt arnawf, neu linyn. Gall hefyd fod yn gasgliad o\nwerthoedd a gweithredyddion. A gall gynnwys enwau newidynnau a galwadau\nswyddogaeth. Dyma fynegiad sy\u2019n cynnwys sawl un o\u2019r elfennau hyn.</p>", "a[href=\"../glossary.html#term-gwall-rhedeg\"]": "<dt id=\"term-gwall-rhedeg\">gwall rhedeg</dt><dd><p>runtime error</p></dd>", "a[href=\"#ymarfer\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2.11.2. </span>Ymarfer<a class=\"headerlink\" href=\"#ymarfer\" title=\"Link to this heading\">#</a></h3><p>Gan ailadrodd fy nghyngor o\u2019r bennod flaenorol, bob tro y dysgwch nodwedd newydd,\ndylech wneud camgymeriadau\u2019n fwriadol i weld beth sy\u2019n mynd o\u2019i le.</p>", "a[href=\"#gofyn-i-gynorthwyydd-rhithwir\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2.11.1. </span>Gofyn i gynorthwyydd rhithwir<a class=\"headerlink\" href=\"#gofyn-i-gynorthwyydd-rhithwir\" title=\"Link to this heading\">#</a></h3><p>Unwaith eto, rwy\u2019n eich annog i ddefnyddio cynorthwyydd rhithwir i ddysgu mwy am\nunrhyw un o bynciau\u2019r bennod hon.</p><p>Os ydych yn chwilfrydig am unrhyw un o\u2019r allweddeiriau a restrais, gallech ofyn\n\u201cPam mae class yn allweddair?\u201d neu \u201cPam na all enwau newidynnau fod yn\nallweddeiriau?\u201d</p>", "a[href=\"#enwau-newidynnau\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2.3. </span>Enwau Newidynnau<a class=\"headerlink\" href=\"#enwau-newidynnau\" title=\"Link to this heading\">#</a></h2><p>Gall enwau newidynnau fod mor hir ag y mynnwch. Gallant gynnwys llythrennau a\nrhifau, ond ni allant ddechrau gyda rhif. Mae\u2019n gyfreithlon defnyddio priflythrennau,\nond mae\u2019n gonfensiynol defnyddio dim ond llythrennau bach ar gyfer enwau newidynnau.</p><p>Yr unig atalnodi a all ymddangos mewn enw newidyn yw\u2019r cymeriad tanlinell, <code class=\"docutils literal notranslate\"><span class=\"pre\">_</span></code>. Fe\u2019i\ndefnyddir yn aml mewn enwau gyda sawl gair, fel <code class=\"docutils literal notranslate\"><span class=\"pre\">your_name</span></code> neu\n<code class=\"docutils literal notranslate\"><span class=\"pre\">airspeed_of_unladen_swallow</span></code>.</p>", "a[href=\"#rhestr-termau-r-bennod\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2.10. </span>Rhestr Termau\u2019r Bennod<a class=\"headerlink\" href=\"#rhestr-termau-r-bennod\" title=\"Link to this heading\">#</a></h2><p><strong>newidyn:</strong>\nEnw sy\u2019n cyfeirio at werth.</p><p><strong>gosodiad neilltuad:</strong>\nGosodiad sy\u2019n neilltuo gwerth i newidyn.</p>", "a[href=\"#sylwadau\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2.8. </span>Sylwadau<a class=\"headerlink\" href=\"#sylwadau\" title=\"Link to this heading\">#</a></h2><p>Wrth i raglenni fynd yn fwy ac yn fwy cymhleth, maent yn mynd yn anoddach eu\ndarllen. Mae ieithoedd ffurfiol yn ddwys, ac mae\u2019n aml yn anodd edrych ar ddarn o\ngod a chanfod beth mae\u2019n ei wneud a pham.</p><p>Am y rheswm hwn, mae\u2019n syniad da ychwanegu nodiadau at eich rhaglenni i esbonio mewn\niaith naturiol beth mae\u2019r rhaglen yn ei wneud. Gelwir y nodiadau hyn yn\n**<a class=\"reference internal\" href=\"../glossary.html#term-sylwad\"><span class=\"xref std std-term\">sylwad</span></a>**au, ac maent yn dechrau gyda\u2019r symbol <code class=\"docutils literal notranslate\"><span class=\"pre\">#</span></code>.</p>", "a[href=\"#id1\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">2.11.3. </span>Ymarfer<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h3><p>Ymarferwch ddefnyddio dehonglydd Python fel cyfrifiannell:</p><p><strong>Rhan 1.</strong> Cyfaint sff\u00ear gyda radiws <span class=\"math notranslate nohighlight\">\\(r\\)</span> yw <span class=\"math notranslate nohighlight\">\\(\\frac{4}{3} \\pi r^3\\)</span>. Beth yw cyfaint\nsff\u00ear gyda radiws 5? Dechreuwch gyda newidyn o\u2019r enw <code class=\"docutils literal notranslate\"><span class=\"pre\">radius</span></code> ac yna neilltuwch y\ncanlyniad i newidyn o\u2019r enw <code class=\"docutils literal notranslate\"><span class=\"pre\">volume</span></code>. Dangoswch y canlyniad. Ychwanegwch sylwadau i\nnodi bod <code class=\"docutils literal notranslate\"><span class=\"pre\">radius</span></code> mewn centimetrau a <code class=\"docutils literal notranslate\"><span class=\"pre\">volume</span></code> mewn centimetrau ciwbig.</p>", "a[href=\"../glossary.html#term-dadl\"]": "<dt id=\"term-dadl\">dadl</dt><dd><p>argument</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
